/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    /** Vendor quote source whose value is the settlement reference rate. Source 0 (default) is the display rate. */
    static final int SETTLEMENT_SOURCE = 2;

    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    /** Display quote on the vendor's default source; a stale quote is returned as-is. */
    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date + "#default", k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date));
        });
    }

    /**
     * Rate applied to card transactions of the given KST settlement date.
     * On a vendor holiday the default quote is the previous business day's value, so the settlement
     * source is asked for the same date instead. Never settles on a stale value.
     */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        FxQuote q = quote(currency, date);
        if (!q.stale()) return q.rate();
        String pair = CurrencyPairs.pairOf(currency);
        FxQuote s = cache.computeIfAbsent(pair + "@" + date + "#settlement", k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date, SETTLEMENT_SOURCE));
        });
        if (s.stale()) {
            throw new IllegalStateException("no settlement rate for " + pair + " on " + date + ": vendor returned a stale value");
        }
        return s.rate();
    }

